logger = pdfgen_utils.getLogger()
DEFAULT_TIMEOUT = 3600
DEFAULT_CHROMIUM_TIMEOUT = 30
MAX_CONCURRENT_SEARCHES = 3
REPLACE_EXTERNAL_IMAGES_WITH_DATA_URIS = True
SNAPSHOT_TYPE = "_ds.snapshot_"
ERROR_VIZ_TYPE = "viz.error"

INPUT_MAX_RESULTS = 1000
NON_PAGINATED_VIZ_MAX_RESULTS = 10000
SMART_SOURCE_MAX_RESULTS = 1
PAGINATED_VISUALIZATION_TYPES = ['splunk.table', 'splunk.events', 'viz.table']
DEFAULT_ROWS_PER_PAGE = 10
NUM_PAGES_DISPLAYED = 5

DEFAULT_EMBED_ENABLED_VALUE = False
DEFAULT_EMBED_EXPIRY_VALUE = 0
EMBED_EXPIRED_DELETION_THRESHOLD = 2678400 # 31 Days Unix Timestamp

KVSTORE_ERROR_STATUS_MESSAGE_MAP = { 400: 'snapshotTooLarge', 404: 'snapshotDefinitionNotFound' }

# Regex to match markdown image links like ![caption](<link>)
# First capturing group is to extract the <link> portion of a markdown image link
IMAGE_LINKS_IN_MARKDOWN_REGEX = r'!\[.*?\]\((?P<link>.*?)\)'

BUILT_IN_SINGLE_VALUE_ICON_TYPES = ['star', 'pencil', 'clock', 'activity', 'default']

VISUAL_EXPORTER_ERROR_MSG = "Confirm that the Splunk Visual Exporter app is turned on to render the dashboard {} to {}."
INVALID_DEFINITION_ERROR_MSG = "Invalid dashboard definition. Correct errors in the dashboard definition to render the dashboard {} to {}."
FEATURE_FLAG_ERROR_MSG = "Set the activate_scheduled_export feature flag in web-features.conf to true to render the dashboard {} to {}."
INVALID_DEFINITION_ERROR_MSG = "Invalid dashboard definition. Correct errors in the dashboard definition to render the dashboard {} to {}."
EMBED_EXPIRED_ERROR_MSG = "Embedding has expired for dashboard {} on {} and it can no longer be published to {}."
EMBED_NOT_ENABLED_ERROR_MSG = "Cannot publish dashboard {} to {} because embedding is not enabled."

CUSTOM_VIZ_ERROR_MSG_CATEGORY = "customVisualizationExportNotSupported"

def create_error_message(message, *error_args):
    return message.format(*error_args)

def parseDataSourceSearchResults(results, fieldOrder, maxRowsToFetch = NON_PAGINATED_VIZ_MAX_RESULTS):
    """
    Parses ResultSet results and fieldOrder into fields and columns format. Do not include fields from fieldOrder
    if there are no columns. Modelled after splunk.pdfgen_table.addRowFromSearchResult()
    """
    parsedResults = {}

    for i, resultRow in enumerate(results):
        if i >= maxRowsToFetch:
            break
        for fieldWithMeta in fieldOrder:
            field = fieldWithMeta.get('name', '')
            existingFieldValues = parsedResults.get(field, [])
            newFieldValues = resultRow.get(field, None)
            # if field value is not null
            # make new field values all strings and append to existingFieldValues to add to parsedResults
            if newFieldValues is None:
                existingFieldValues.append(newFieldValues)
            elif isinstance(newFieldValues, search.RawEvent):
                fieldValuesStr = newFieldValues
                existingFieldValues.append(str(fieldValuesStr))
            elif len(newFieldValues) > 1:
                fieldValueStrings = [str(x) for x in newFieldValues]
                existingFieldValues.append(fieldValueStrings)
            else:
                fieldValuesStr = newFieldValues[0]
                existingFieldValues.append(str(fieldValuesStr))
            parsedResults[field] = existingFieldValues
    columns = []
    fields = []
    for fieldWithMeta in fieldOrder:
        field = fieldWithMeta.get('name', '')
        columnValues = parsedResults[field]
        columns.append(columnValues)
        fields.append(fieldWithMeta)
    return fields, columns


def getResultCount(searchManager):
    try:
        if searchManager.job is None:
            return 0
        return int(searchManager.job.resultCount)
    except Exception:
        return 0

def _createDsSnapshotWithOptions(fields, columns, meta={}):
    return {
        'type': SNAPSHOT_TYPE,
        'options': {
            'data': {
                'fields': fields,
                'columns': columns
            },
            'meta': meta,
        }
    }

def _createEmptyDsSnapshot():
    return _createDsSnapshotWithOptions([], [], {})

def getDataSourceSearchResults(searchManager, resolvedDataSources, erroredDataSources,
                               ds, checkRiskyCommand, dataSourceDef, maxRowsToFetch = NON_PAGINATED_VIZ_MAX_RESULTS):
    """
    Dispatches searchManager to retrieve search results for ds in fields/columns format. If the search completes
    successfully, the dataSource is added to resolvedDataSources with the corresponding results stored in a _ds.snapshot_
    format. If there is an error, the dataSource is added to erroredDataSources with the corresponding error message.
    """
    logger.debug("getting search results for dataSource %s" % ds)
    if searchManager is None:
        erroredDataSources[ds] = 'Unable to create search.'
        return
    
    timeoutTime = int(time.time()) + DEFAULT_TIMEOUT
    try:
        searchManager.dispatch(checkRiskyCommand=checkRiskyCommand)
        while not searchManager.isComplete() and not searchManager.isRealtime():
            time.sleep(1)
            currentTime = int(time.time())
            timedOut = currentTime > timeoutTime
            if timedOut:
                searchManager.cancel()
                erroredDataSources[ds] = 'Search timed out after %s seconds.' % DEFAULT_TIMEOUT
                return

        meta = {
            'totalCount': getResultCount(searchManager),
            'originalDefinition': dataSourceDef,
            'status': 'done',
        }

        # If there's a job.id put it in the meta.sid
        try:
            meta['sid'] = searchManager.job.id
        except AttributeError as e:
            logger.warning("Exception setting meta.sid: %s", str(e))

        results = searchManager.results()
        fieldOrder = results.fieldOrderWithMeta
        fields, columns = parseDataSourceSearchResults(results, fieldOrder, maxRowsToFetch)

        # SPL-286010: post-process search uses parent's resultCount, not its own
        if isinstance(searchManager, PostProcessSearchManager):
            meta['totalCount'] = 0 if not len(columns) else len(columns[0])

        # modify data obj to contain search results as _ds.snapshot
        dsSnapshot = _createDsSnapshotWithOptions(fields, columns, meta)

        dataSourceName = dataSourceDef.get('name')
        if dataSourceName is not None:
            dsSnapshot['name'] = dataSourceName
        enableSmartSources = dataSourceDef.get('options', {}).get(
            'enableSmartSources')
        smartSourceTokens = {}
        if enableSmartSources is not None:
            dsSnapshot['options']['enableSmartSources'] = enableSmartSources
            if (enableSmartSources and dataSourceName is not None):
                try:
                    smartSourceTokens = create_tokens_from_results(fields, columns, results.job, dataSourceName)
                except Exception:
                    logger.error("Failed to parse smart source tokens: %s", ds)
        resolvedDataSources[ds] = { "definition": dsSnapshot, "smartSourceTokens": smartSourceTokens }
    except Exception as e:
        if isinstance(e, AuthorizationFailed) and checkRiskyCommand and 'check_risky_command' in e.extendedMessages:
            # This is a special case for chain searches containing risky commands, which throw an AuthorizationFailed
            # exception which does not contain any useful info for security reasons. Because of this, we need to return
            # a more generic risky commands error message.
            errorMessage = 'Found potentially risky commands.'
        else:
            errorMessage = str(e)
        erroredDataSources[ds] = errorMessage
        return


def getDataURI(url, collection, sessionKey, includeExternal=False, trustedDomains=None, save_snapshot=False):
    """
    return the data URI for a given url, if there is an error accessing the url, return None.
    If the url is not trusted, then return None
    """
    if url is None:
        return None

    kvstoreIdentifier = 'splunk-enterprise-kvstore://'
    if not url.startswith(kvstoreIdentifier):
        if includeExternal:
            return getDataURIForExternalImage(url, trustedDomains, save_snapshot)
        return None
    if not collection:
        return None
    try:
        key = url.split(kvstoreIdentifier)[1]
        uri = entity.buildEndpoint(
            ['storage', 'collections', 'data', collection, key],
            namespace='splunk-dashboard-studio'
        )
        jobResponseHeaders, jobResponseBody = rest.simpleRequest(
            uri, method='GET', sessionKey=sessionKey, getargs={'output_mode': 'json'})
        searchJob = json.loads(jobResponseBody)
        return searchJob.get('dataURI')
    except Exception:
        return None



def mergeOptions(options1, options2):
    """
    Return new object with merged options1 and options2, where options1 takes precedence
    """
    mergedOptions = copy.deepcopy(options2)
    mergedOptions.update(options1)
    return mergedOptions


def getMergedDefaultOptionsForDataSourceType(defaults, dataSourceType):
    """
    Return a merged set of global and type specific default options for the given data source type.
    Type specific default options take precedence over global default options. Exclude query from these options.
    """
    if defaults == {} or dataSourceType is None:
        return {}

    globalOptions = defaults.get('dataSources', {}).get(
        'global', {}).get('options', {})
    typeSpecificOptions = defaults.get('dataSources', {}).get(
        dataSourceType, {}).get('options', {})
    mergedOptions = mergeOptions(typeSpecificOptions, globalOptions)
    if mergedOptions.get("query") is not None:
        del mergedOptions["query"]
    return mergedOptions


def getMergedOptionsForDataSource(dataSource, mergedDefaultOptions, defaults, dsName):
    """
    Return a merged set of default and data source specific options for the given data source.
    Data source specific options take precedence over default options.
    """
    logger.debug("getting merged options for dataSource %s" % dsName)
    dataSourceType = dataSource.get('type')
    dataSourceOptions = dataSource.get('options', {})
    if not mergedDefaultOptions.get(dataSourceType, {}):
        mergedDefaultOptions[dataSourceType] = getMergedDefaultOptionsForDataSourceType(
            defaults, dataSourceType)
    defaultOptions = mergedDefaultOptions[dataSourceType]
    return mergeOptions(dataSourceOptions, defaultOptions)


def runSearches(searchQueue, resolvedDataSources, erroredDataSources, checkRiskyCommand):
    """
    Runs all the searches in the searchQueue
    """
    while not searchQueue.empty():
        searchManager, datasourceId, dataSourceDef, maxRowsToFetch = searchQueue.get()
        getDataSourceSearchResults(
            searchManager, resolvedDataSources, erroredDataSources,
            datasourceId, checkRiskyCommand, dataSourceDef, maxRowsToFetch)
        searchQueue.task_done()

def getElementsReferencingDataSource(dsId, elementMap):
    elements_referencing_ds = []
    for elementId, elementDef in elementMap.items():
        referencedDataSources = elementDef.get('dataSources', {})
        for key, referencedDsId in referencedDataSources.items():
            if referencedDsId == dsId:
                elements_referencing_ds.append({
                    "id": elementId,
                    "definition": elementDef
                })

    return elements_referencing_ds

def getMaxResultsToFetch(dsId, dataSource, definition):
    """
    Return the number of results to fetch for a given data source, taken from the 
    max count needed by anything that uses the data source. These are as follows:
        Smart sources use 1 row
        Inputs use 1000 rows
        Non-paginated viz's use 10000 rows
        Paginated viz's need enough rows to render the first 5 pages
    If the data source is unused, then returns 0
    """
    maxResultsToFetch = 0
    enableSmartSources = dataSource.get('options', {}).get('enableSmartSources', False)
    if enableSmartSources:
        maxResultsToFetch = SMART_SOURCE_MAX_RESULTS

    visualizations = definition.get('visualizations', {})
    inputs = definition.get('inputs', {})
    inputsReferencingDs = getElementsReferencingDataSource(dsId, inputs)
    visualizationsReferencingDs = getElementsReferencingDataSource(dsId, visualizations)

    if len(inputsReferencingDs) > 0:
        maxResultsToFetch = max(maxResultsToFetch, INPUT_MAX_RESULTS)

    for visualization in visualizationsReferencingDs:
        vizDef = visualization.get('definition', {})
        if vizDef.get('type', '') in PAGINATED_VISUALIZATION_TYPES:
            resultsPerPage = vizDef.get('options', {}).get('count', DEFAULT_ROWS_PER_PAGE)
            resultsNeeded = resultsPerPage * NUM_PAGES_DISPLAYED + 1
            maxResultsToFetch = max(resultsNeeded, maxResultsToFetch)
        else:
            maxResultsToFetch = max(maxResultsToFetch, NON_PAGINATED_VIZ_MAX_RESULTS)

    return maxResultsToFetch

def cancelAllSearches(managerMap):
    for dsId, searchDict in managerMap.items():
        try:
            searchDict['search_manager'].cancel()
        except Exception:
            logger.exception('Error while cancelling datasource %s', dsId)

def modifyDataSourceSearches(definition, namespace, owner, sessionKey):
    """
    For every dataSource in the definition, run the search and replace it with the results as _ds.snapshot_.
    The original definition is modified. If a dataSource search results in an error, the dataSource name 
    is added to the erroredDataSources dictionary, with the corresponding error message.
    """
    logger.debug("modifying dataSource searches")
    dataSources = definition.get("dataSources", {})
    defaults = definition.get("defaults", {})
    mergedDefaultOptions = {}
    managerMap = {}
    erroredDataSources = {}
    resolvedDataSources = {}
    duplicateDataSources = {}
    checkRiskyCommand = pdfgen_utils.isRiskyCommandCheckDashboardEnabled(
        sessionKey)

    search_grouping = get_search_grouping(dataSources)
    for search_group in search_grouping:
        currentSearches = {}
        for ds in search_group:
            dataSource = dataSources[ds]
            dataSource["options"] = getMergedOptionsForDataSource(
                dataSource, mergedDefaultOptions, defaults, ds)
            replace_smart_source_tokens(dataSource["options"], resolvedDataSources)
            if has_token(json.dumps(dataSource)):
                errorMessage = "Set token value to render visualization"
                erroredDataSources[ds] = errorMessage
            elif dataSource.get("type") != "ds.test" and dataSource.get("type") != SNAPSHOT_TYPE:
                search = get_search_manager(
                    ds, dataSources, managerMap, namespace, owner, sessionKey)
                maxResultsToFetch = getMaxResultsToFetch(ds, dataSource, definition)
                # don't execute searches that are unused by inputs/viz's
                if maxResultsToFetch == 0:
                    resolvedDataSources[ds] = {
                        "definition": _createEmptyDsSnapshot(),
                        "smartSourceTokens": {}
                    }
                else:
                    currentSearches[ds] = [search['cache_key'] or ds, maxResultsToFetch, search['search_manager'], dataSource]

        searchQueue, duplicateDataSources = create_search_queue(currentSearches)
        for _ in range(MAX_CONCURRENT_SEARCHES):
            thread = Thread(target=runSearches, args=[
                            searchQueue, resolvedDataSources, erroredDataSources, checkRiskyCommand])
            thread.start()
        searchQueue.join()
        clone_duplicate_data_sources(duplicateDataSources, resolvedDataSources, dataSources)
        cancelAllSearches(managerMap)

    for ds in resolvedDataSources:
        logger.debug("Resolving datasource %s" % ds)
        dataSources[ds] = resolvedDataSources[ds].get("definition")
    for ds in erroredDataSources:
        errorMessage = erroredDataSources[ds]
        logger.error("Error for DataSource %s: %s" % (ds, errorMessage))
        dataSources[ds] = _createDsSnapshotWithError(errorMessage)
    logger.debug(definition)
    return erroredDataSources

def _createDsSnapshotWithError(errorMessage):
    """
    Return a _ds.snapshot_ with a given error message
    """
    return {
        'type': SNAPSHOT_TYPE,
        'options': {
            'error': errorMessage
        }
    }

def _createErrorVizWithMessageCategory(messageCategory):
    """
    Return a viz.error configured with the given error message category
    """
    return {
        'type': ERROR_VIZ_TYPE,
        'options': {
            'errorMessageCategory': messageCategory
        }
    }

def generateRandomId(idPrefix):
    """
    Generate a random id in the format of idPrefix_<random_string>
    """
    return '%s_%s' % (idPrefix, str(uuid.uuid4()))

def replaceVizDataSourceWithError(definition, vizName, errorMessage):
    """
    Replace a visualization's data source with a _ds.snapshot_ containing a given
    error message
    """
    visualization = definition['visualizations'][vizName]
    dsSnapshot = _createDsSnapshotWithError(errorMessage)
    if 'dataSources' in definition:
        dataSources = definition['dataSources']
    else:
        dataSources = {}
        definition['dataSources'] = dataSources

    dsId = generateRandomId('ds')
    definition['dataSources'][dsId] = dsSnapshot
    visualization['dataSources'] = {
        'primary': dsId
    }

def modifyBackgroundImageDataURI(definition, sessionKey, is_tabbed_dashboard, includeExternal=False, trustedDomains=None, save_snapshot=False):
    """
    If there is a backgroundImage, replace the URL with the data URI. If there
    is an error retrieving the data URI, delete the backgroundImage from layout options.
    """
    if is_tabbed_dashboard:
        layout_definitions = definition.get('layout', {}).get('layoutDefinitions', {})
        
        for layout_key in layout_definitions:
            logger.debug('replacing background image URL with data URI for a tabbed dashboard for layout %s' % layout_key)
            layout_definition = layout_definitions.get(layout_key, {})
            replace_background_image_data_uri(layout_definition, sessionKey, includeExternal, trustedDomains, save_snapshot)
    else:
        logger.debug('replacing background image URL with data URI')
        layout_definition = definition.get('layout', {})
        replace_background_image_data_uri(layout_definition, sessionKey, includeExternal, trustedDomains, save_snapshot)

def replace_background_image_data_uri(layout_definition, sessionKey, includeExternal, trustedDomains, save_snapshot):
    if layout_definition.get('options', {}).get('backgroundImage'):
        url = layout_definition['options']['backgroundImage'].get('src')
        dataURI = getDataURI(url, 'splunk-dashboard-images',
                             sessionKey, includeExternal, trustedDomains, save_snapshot)
        if dataURI:
            layout_definition['options']['backgroundImage']['src'] = dataURI
        else:
            del layout_definition['options']['backgroundImage']

def replace_custom_viz_with_error(definition, vizName):
    logger.debug("replacing custom visualization with error message for visualization {}".format(vizName))
    errorViz = _createErrorVizWithMessageCategory(CUSTOM_VIZ_ERROR_MSG_CATEGORY)
    definition['visualizations'][vizName] = errorViz

def modifyVizDataURI(definition, vizName, sessionKey, includeExternal=False, trustedDomains=None, save_snapshot=False):
    """
    For image, singlevalueicon and choropleth visualizations, replace the URL with the data URI.
    If there is an error retrieving the data URI, convert the visualization to viz.error.
    """
    logger.debug(
        "replacing image/icon URL with data URI for visualization %s" % vizName)
    viz = definition['visualizations'][vizName]
    vizType = viz.get('type')
    if vizType == 'viz.img' or vizType == 'splunk.image':
        url = viz.get('options', {}).get('src')
        if url is None:
            return
        dataURI = getDataURI(url, 'splunk-dashboard-images',
                             sessionKey, includeExternal, trustedDomains, save_snapshot)
        if dataURI:
            definition['visualizations'][vizName]['options']['src'] = dataURI
        else:
            replaceVizDataSourceWithError(definition, vizName, 'Image not found')
            del definition['visualizations'][vizName]['options']['src']

    elif vizType == 'viz.singlevalueicon' or vizType == 'splunk.singlevalueicon':
        url = viz.get('options', {}).get('icon')
        if url is None:
            return
        # Do not try to resolve built in icons to a data uri
        if url.lower() in BUILT_IN_SINGLE_VALUE_ICON_TYPES:
            return
        
        dataURI = getDataURI(url, 'splunk-dashboard-icons',
                             sessionKey, includeExternal, trustedDomains, save_snapshot)
        if dataURI:
            definition['visualizations'][vizName]['options']['icon'] = dataURI
        else:
            del definition['visualizations'][vizName]['options']['icon']

    elif vizType == 'splunk.choropleth.svg':
        url = viz.get('options', {}).get('svg')
        if url is None:
            return
        dataURI = getDataURI(url, 'splunk-dashboard-images',
                             sessionKey, includeExternal, trustedDomains, save_snapshot)
        if dataURI:
            definition['visualizations'][vizName]['options']['svg'] = dataURI
        else:
            replaceVizDataSourceWithError(definition, vizName, 'SVG not found')
            del definition['visualizations'][vizName]['options']['svg']

    elif vizType == 'splunk.markdown':
        markdown = viz.get('options', {}).get('markdown')
        if markdown is None:
            return
        for markdown_image_link_match in re.finditer(IMAGE_LINKS_IN_MARKDOWN_REGEX, markdown):
            image_link_markdown = markdown_image_link_match.group(0)
            link = markdown_image_link_match.group('link')
            if link:
                dataURI = getDataURI(link, None,
                                     sessionKey, includeExternal, trustedDomains, save_snapshot)
                if dataURI is None:
                    dataURI = ''
                image_link_markdown_with_replaced_url = image_link_markdown.replace(link, dataURI)
                markdown = markdown.replace(image_link_markdown, image_link_markdown_with_replaced_url)
        viz.get('options', {})['markdown'] = markdown

def checkVisualExporterInstalledAndEnabled(sessionKey):
    """
    Check that Splunk Visual Exporter is installed by calling services/apps/local/splunk-visual-exporter
    """
    try:
        response, content = rest.simpleRequest(
            'apps/local/splunk-visual-exporter', sessionKey=sessionKey, getargs={'output_mode': 'json'})
        appResponse = json.loads(content)
        isDisabled = appResponse.get('entry', [{}])[0].get('content', {}).get('disabled')
        return not isDisabled
    except Exception:
        return False
    
def get_unique_custom_visualizations(visualizations):
    """
    Returns the unique custom visualizations present in the list of
    visualizations. Expects visualizations to be of the form of the entry field
    from data/ui/visualizations.

    ex: set({'bullet_graph_app.bullet_graph', 'horseshoe_meter_app.horseshoe_meter'})
    """
    custom_visualizations = set()
    for viz in visualizations:
        vizApp = viz['acl']['app']

        # visualizations with acl.app == 'system' are native to splunk
        if vizApp != 'system':
            customViz = "{}.{}".format(vizApp, viz['name'])
            custom_visualizations.add(customViz)
    return custom_visualizations

def get_installed_custom_visualizations(session_key, namespace):
    """
    Retrieves the visualizations from data/ui/visualizations and filters the results to only include custom visualizations
    (i.e, visualizations where the acl.app is not 'system'). These results are formatted into a set to only return the 
    unique custom visualizations.

    ex: set({'bullet_graph_app.bullet_graph', 'horseshoe_meter_app.horseshoe_meter'})
    """
    # construct uri to installed visualizations (data/ui/visualizations)
    entity_class = ['data', 'ui', 'visualizations']
    visualizations_uri = entity.buildEndpoint(
        entity_class,
        namespace=namespace,
    )

    try:
        response, content = rest.simpleRequest(visualizations_uri, sessionKey=session_key, getargs={'output_mode': 'json'})
        visualizations_response = json.loads(content)
        visualizations = visualizations_response.get('entry', [])
        custom_visualizations = get_unique_custom_visualizations(visualizations)

        return custom_visualizations
    except Exception as e:
        # Log exception if unable to retrieve custom visualizations and return empty set
        logger.exception("failed to retrieve installed custom visualizations for scheduled export: {}".format(str(e)))
        return set()
    
def remove_unsupported_options(definition: dict):
    visualizations: dict = definition.get('visualizations', {})
    for viz_id, viz_def in visualizations.items():
        viz_type: str = viz_def.get('type')
        viz_options: dict = viz_def.get('options', {})
        if viz_type == 'splunk.map':
            # Only splunk map tiles are supported in scheduled export
            viz_options.pop('baseLayerTileServer', None)
            viz_options.pop('baseLayerTileServerType', None)

def send_studio_pdf_telemetry(dashboardName, fileFormat, dashboardTelemetryData, owner, namespace, sessionKey):
    app = namespace if namespace else pv.get_default_app(sessionKey)
    payload = {
        'type': 'scheduled.exports.sent',
        'data': {
            'viewId': dashboardName,
            'viewType': 'Studio',
            'fileFormat': fileFormat,
            'dashboardData': dashboardTelemetryData,
            'exporter': 'Chromium',
            'route': '/pdfgen/render',
        }
    }

    post_telemetry_metric(payload, {
        'session_key': sessionKey,
        'owner': owner,
        'app': app
    })

def create_snapshot_error_response(errors, status=400):
    return {
        'status': status,
        'error_messages': errors
    }

def get_snapshot_view_name(dashboard_id):
    return '_SnapshotView__{}'.format(dashboard_id)

def create_snapshot(save_snapshot_uri, session_key, getargs, postargs):
    response, content = rest.simpleRequest(save_snapshot_uri, sessionKey=session_key, getargs=getargs, postargs=postargs, method='POST')
    return (response, content)

def delete_snapshot(snapshot_uri, session_key, getargs):
    response, content = rest.simpleRequest(snapshot_uri, sessionKey=session_key, getargs=getargs, method='DELETE')
    return (response, content)

def escape_string_for_xml(string):
    # saxutils.escape only escapes >, <, and & and not quotations like lodash
    return escape(string, entities={
        "'": "&#39;",
        '"': "&quot;"
    })

def create_snapshot_definition(theme, embed_expiry, dashboard_id, kvstore_key):
    escaped_theme = escape_string_for_xml(str(theme))
    escaped_embed_expiry = escape_string_for_xml(str(embed_expiry))
    escaped_dashboard_id = escape_string_for_xml(str(dashboard_id))
    return '''
<dashboard version="2" theme="{}" isDashboard="false" embed.enabled="true" embed.expiry="{}" isVisible="false" snapshotLocation="{}">
    <label>{}</label>
    <definition><![CDATA[{{}}]]></definition>
</dashboard>
'''.strip().format(escaped_theme, escaped_embed_expiry, kvstore_key, escaped_dashboard_id)

