def get_existing_snapshot_kvstore_key(session_key, dashboard_id, namespace, owner):
    snapshot_xml = get_snapshot_xml(dashboard_id, namespace, owner, session_key, [])

    # this means that the snapshot wasn't already in created
    if snapshot_xml is None:
        return ''
        
    # Creating a snapshot view from Studio modal does not include the snapshotLocation attribute,
    # so the definition will not be in KVStore yet
    return snapshot_xml.attrib.get('snapshotLocation', '')

def delete_nobody_snapshot(session_key, key):
    try:
        uri = entity.buildEndpoint(
                ['storage', 'collections', 'data', 'splunk-dashboard-snapshots', key],
                namespace='splunk-dashboard-studio'
            )
        rest.simpleRequest(uri, method='DELETE', sessionKey=session_key)
    except Exception as e:
        logger.exception('failed to delete snapshot for nobody with key=%s: %s', key, str(e))

def save_snapshot_data_to_kvstore(definition, session_key, dashboard_id, namespace, owner):
    # Check if snapshot already exists in KVStore, overwrite if it does so we keep using 
    # the same key for the same dashboard
    
    key = get_existing_snapshot_kvstore_key(session_key, dashboard_id, namespace, owner)
    
    uri = entity.buildEndpoint(
            ['storage', 'collections', 'data', 'splunk-dashboard-snapshots', key],
            namespace='splunk-dashboard-studio',
            owner=owner
        )

    try:
        try:
            response, body = rest.simpleRequest(
                uri, method='POST', sessionKey=session_key, jsonargs=json.dumps({ 'definition': json.dumps(definition) }))
        except splunk.ResourceNotFound:
            # If the key is not found in the user scoped path, we should attempt 
            # to delete it from the nobody scoped path before saving to a new 
            # user scoped key
            delete_nobody_snapshot(session_key, key)
            uri = entity.buildEndpoint(
                ['storage', 'collections', 'data', 'splunk-dashboard-snapshots'],
                namespace='splunk-dashboard-studio',
                owner=owner
            )
            response, body = rest.simpleRequest(
                uri, method='POST', sessionKey=session_key, jsonargs=json.dumps({ 'definition': json.dumps(definition) }))
        
        if response.status == 201 or response.status == 200:
            return json.loads(body).get('_key')
        elif response.status in KVSTORE_ERROR_STATUS_MESSAGE_MAP.keys():
            # Check for custom error message in map (400 errors)
            return json.dumps(create_error_snapshot_definition(definition, KVSTORE_ERROR_STATUS_MESSAGE_MAP[response.status]))
        else:
            # Fallback to generic kvstore not ready error
            return json.dumps(create_error_snapshot_definition(definition, 'kvStoreNotReady'))
    except Exception as e:
        logger.error(str(e))
        return key

def save_snapshot_dashboard(dashboard_id, definition, theme, owner, namespace, session_key, embed_expiry):
    kvstore_key = save_snapshot_data_to_kvstore(definition, session_key, dashboard_id, namespace, owner)
    postargs = {
        'eai:data': create_snapshot_definition(theme, embed_expiry, dashboard_id, kvstore_key)
    }
    getargs = { 'output_mode': 'json' }

    snapshot_view_name = get_snapshot_view_name(dashboard_id)
    entity_class = ['data', 'ui', 'views', snapshot_view_name]
    save_snapshot_uri = entity.buildEndpoint(
        entity_class,
        namespace=namespace,
        owner=owner
    )
    try:
        response, content = create_snapshot(save_snapshot_uri, session_key, getargs, postargs)
        link = json.loads(content)['entry'][0]['id']
        return {
            'status': response.status,
            'location': link
        }
    except RESTException:
        error_msg = 'Could not create snapshot for dashboard %s' % snapshot_view_name
        logger.exception(error_msg)
        return create_snapshot_error_response(error_msg)

def delete_expired_snapshot_dashboard(snapshot_xml, dashboard_id, owner, namespace, session_key):
    """
    Attempt to delete an expired dashboard snapshot if it has been expired for 1 month.
    Returns: boolean value indicating if deletion was attempted and successful.
    """
    xml_embed_expiry_value = snapshot_xml.attrib.get('embed.expiry', DEFAULT_EMBED_EXPIRY_VALUE)
    embed_expiry_datetime = get_embed_expiry_timestamp(xml_embed_expiry_value)
    current_datetime = datetime.datetime.now(tz=datetime.timezone.utc)

    # If embed has not been expired for longer than the deletion threshold, exit
    time_embed_expired = int((current_datetime - embed_expiry_datetime).total_seconds())
    if time_embed_expired < EMBED_EXPIRED_DELETION_THRESHOLD:
        return False

    getargs = { 'output_mode': 'json' }
    
    snapshot_view_name = get_snapshot_view_name(dashboard_id)
    entity_class = ['data', 'ui', 'views', snapshot_view_name]
    snapshot_uri = entity.buildEndpoint(
        entity_class,
        namespace=namespace,
        owner=owner
    )
    try:
        delete_snapshot(snapshot_uri, session_key, getargs)
        return True
    except RESTException:
        error_msg = 'Could not delete snapshot for dashboard %s' % snapshot_view_name
        logger.exception(error_msg)
        return False

def get_snapshot_xml(dashboardName, namespace, owner, sessionKey, studioErrors):
    try:
        existing_snapshot_definition = pv.getStudioDashboardContent(
            get_snapshot_view_name(dashboardName), 
            namespace=namespace, 
            owner=owner, 
            sessionKey=sessionKey)
    except splunk.ResourceNotFound:
        existing_snapshot_definition = None
    if existing_snapshot_definition is None:
        logger.error('Cannot save snapshot because snapshot view does not exist for dashboard: %s', dashboardName)
        studioErrors.append(create_error_message(EMBED_NOT_ENABLED_ERROR_MSG, dashboardName, 'URL'))
        return None
        
    return et.fromstring(splunk.util.toUTF8(existing_snapshot_definition))

def get_embed_expiry_timestamp(xml_embed_expiry_value):    
    try:
        embed_expiry_epoch_seconds = int(xml_embed_expiry_value)
    except ValueError:
        logger.error('Invalid epoch seconds expiry value specified for embed.expiry. Value specified was %s', xml_embed_expiry_value)
        embed_expiry_epoch_seconds = DEFAULT_EMBED_EXPIRY_VALUE
    
    embed_expiry_datetime = datetime.datetime.fromtimestamp(
    timestamp=embed_expiry_epoch_seconds, tz=datetime.timezone.utc)
    return embed_expiry_datetime

def can_embed(snapshot_xml, dashboardName, studioErrors):
    xml_embed_enabled_value = snapshot_xml.attrib.get('embed.enabled', DEFAULT_EMBED_ENABLED_VALUE)
    xml_embed_expiry_value = snapshot_xml.attrib.get('embed.expiry', DEFAULT_EMBED_EXPIRY_VALUE)

    try:
        embed_enabled = splunk.util.normalizeBoolean(xml_embed_enabled_value, enableStrictMode=True)
    except ValueError:
        logger.error('Non-boolean value specified for embed.enabled. Value specified was %s', xml_embed_enabled_value)
        embed_enabled = DEFAULT_EMBED_ENABLED_VALUE
    if not embed_enabled:
        logger.error('Embedding is not enabled for dashboard %s', dashboardName)
        studioErrors.append(create_error_message(EMBED_NOT_ENABLED_ERROR_MSG, dashboardName, 'URL'))
        return False

    current_datetime = datetime.datetime.now(tz=datetime.timezone.utc)
    embed_expiry_datetime = get_embed_expiry_timestamp(xml_embed_expiry_value)
    if embed_expiry_datetime < current_datetime:
        embed_expiry_iso_string = embed_expiry_datetime.isoformat()
        logger.error('Embedding for dashboard %s expired on %s', dashboardName, embed_expiry_iso_string)
        studioErrors.append(create_error_message(EMBED_EXPIRED_ERROR_MSG, dashboardName, embed_expiry_iso_string, 'URL'))
        return False
    
    return True

def convertDashboardToPdfContent(sessionKey, namespace, owner, studioDefinition, dashboardName, studioErrors, chromiumTimeout, screenshotDelay, exportMaxFileSizeMB, exportMaxScaleFactor, fileFormat, save_snapshot):
    """
    Convert the given definition to pdf content. Return False if service is not enabled or available.
    """
    # ensure correct permissions and services are enabled and available    
    if save_snapshot:
        snapshot_xml = get_snapshot_xml(dashboardName, namespace, owner, sessionKey, studioErrors)
        if snapshot_xml is None:
            return create_snapshot_error_response(studioErrors)
        if not can_embed(snapshot_xml, dashboardName, studioErrors):
            # Attempt to remove the expired snapshot if it has been expired long enough
            delete_expired_snapshot_dashboard(snapshot_xml, dashboardName, owner, namespace, sessionKey)
            return create_snapshot_error_response(studioErrors)
        embed_expiry = snapshot_xml.attrib.get('embed.expiry', DEFAULT_EMBED_EXPIRY_VALUE)

    # ensure that Splunk Visual Exporter is installed and enabled
    isAppInstalledAndEnabled = checkVisualExporterInstalledAndEnabled(sessionKey)
    if isAppInstalledAndEnabled is not True and not save_snapshot:
        logger.info('Splunk Visual Exporter is either not installed or is disabled')
        studioErrors.append(create_error_message(VISUAL_EXPORTER_ERROR_MSG, dashboardName, fileFormat))
        return False

    # get CSP header and trusted domains
    csp_header, trustedDomains = extractCSPAndTrustedDomains(
        get_dashboards_csp_settings(sessionKey))

    # convert dashboard definition from xml to json
    xmlDefinition = et.fromstring(splunk.util.toUTF8(studioDefinition))
    theme = xmlDefinition.attrib['theme'] if 'theme' in xmlDefinition.attrib else 'light'
    stringDefinition = xmlDefinition.find('definition').text
    try:
        definition = json.loads(stringDefinition)
    except json.JSONDecodeError:
        logger.exception('Invalid dashboard definition')
        studioErrors.append(create_error_message(INVALID_DEFINITION_ERROR_MSG, dashboardName, fileFormat))
        return False
    # send telemetry
    if dashboardName:
        telemetryData = generate_telemetry_data(definition)
        send_studio_pdf_telemetry(
            dashboardName, fileFormat, telemetryData, owner, namespace, sessionKey)
    is_tabbed_dashboard = 'tabs' in definition.get('layout', {}) and 'layoutDefinitions' in definition.get('layout', {})

    installed_custom_visualizations = set()
    # modify definition to prepare it for conversion to pdf content
    if save_snapshot:
        disable_search_inputs(definition)
    else:
        # retrieve installed custom visualizations only for scheduled exports to display errors
        installed_custom_visualizations = get_installed_custom_visualizations(sessionKey, namespace)

    replace_tokens(definition, sessionKey, namespace, dashboardName, save_snapshot)
    remove_unsupported_options(definition)

    visualizations = definition.get('visualizations', {})
    for vizName in visualizations:
        modifyVizDataURI(definition, vizName, sessionKey,
                            REPLACE_EXTERNAL_IMAGES_WITH_DATA_URIS, trustedDomains, save_snapshot)
        # Replace any custom viz with error messages for scheduled exports if present in installed custom viz
        vizType = visualizations[vizName]['type']
        if not save_snapshot and vizType in installed_custom_visualizations:
            replace_custom_viz_with_error(definition, vizName)
    
    modifyDataSourceSearches(
        definition, namespace, owner, sessionKey)
    modifyBackgroundImageDataURI(
        definition, sessionKey, is_tabbed_dashboard, REPLACE_EXTERNAL_IMAGES_WITH_DATA_URIS, trustedDomains, save_snapshot)
    
    if save_snapshot:
        return save_snapshot_dashboard(dashboardName, definition, theme, owner, namespace, sessionKey, embed_expiry)
    else: 
        return get_screenshot(definition, theme, sessionKey, studioErrors, chromiumTimeout, screenshotDelay, exportMaxFileSizeMB, exportMaxScaleFactor, fileFormat=fileFormat)
